INSERT INTO `comment` (`id`, `content`, `updated_at`, `user_id`, `post_id`, `parent_id`, `valid`) VALUES
(1, '真的很害怕用卸妝油 洗完臉還是油油😨', '2025-04-17 07:00:07', 1, 258563475, NULL, 1),
(2, '好喜歡他的包裝設計～', '2025-04-17 10:24:07', 2, 258563475, NULL, 1),
(3, '保養後的光澤好美欸～而且妝感好粉嫩好可愛', '2025-04-17 07:03:20', 3, 258571954, NULL, 1),
(4, '妝化得好讚😍😍', '2025-04-17 07:03:40', 4, 258571954, NULL, 1),
(5, '皮膚超好啊❤️', '2025-04-17 07:31:24', 5, 258571954, NULL, 1),
(6, '第二張還以為是哪個女團偶像！太美了！', '2025-04-17 07:35:21', 6, 258571954, NULL, 1),
(7, '皮膚超級亮！ 想學你的鼻影打法 ❤️好好看', '2025-04-17 08:03:08', 7, 258571954, NULL, 1),
(8, '後續妝容也很貼耶! 整個保養完膚質超級好', '2025-04-17 08:28:44', 8, 258571954, NULL, 1),
(9, '可以問唇膏嗎 好美！！', '2025-04-17 10:55:18', 9, 258571954, NULL, 1),
(10, '這個膚況太讓人羨慕！妳好漂亮喔呦', '2025-04-17 10:21:05', 10, 258571954, NULL, 1),
(11, '影片看起來超燒', '2025-04-17 11:10:11', 11, 258571954, NULL, 1),
(12, '已經刪除的內容就像 Dcard 一樣，錯過是無法再相見的！', '2025-04-16 15:33:12', 12, 258565532, NULL, 1),
(13, '一跟三我都有！\nYsl粉質真的有在細 持妝力超好\n跟午夜粉底搭是100分\nnars的話比較沒那麼持久 但妝感也不錯', '2025-04-16 15:33:38', 13, 258565532, NULL, 1),
(14, 'nars那個根本堪比打亮了吧XDD\n閃片超大', '2025-04-17 03:56:23', 14, 258565532, NULL, 1),
(15, '我也喜歡紫調去黃提亮～\n帶亮粉我真的不行🥹', '2025-04-17 05:34:11', 15, 258565532, NULL, 1),
(16, '毛孔人路過\n一直都在用帶亮粉定妝⋯原來以前都用錯🥹', '2025-04-17 06:49:47', 16, 258565532, NULL, 1),
(17, '這幾顆包裝都超好看的\n觀望中👀', '2025-04-17 06:56:54', 17, 258565532, NULL, 1),
(18, '三個打開的紫色都好漂亮', '2025-04-17 08:09:57', 18, 258565532, NULL, 1),
(19, '皮革蜜粉的柔焦感很漂亮耶\n感覺最適合瑕疵皮', '2025-04-17 09:38:21', 19, 258565532, NULL, 1),
(20, '如果皮膚不黃 是不是都買膚色或透明的就好啊', '2025-04-17 09:49:56', 20, 258565532, NULL, 1),
(21, '艾杜紗真的很好控制新手友善…但每次用每次暈 請問大家有推薦其他款嗎？還是膠筆畫眼尾都一定會暈呢？🙏', '2025-04-16 18:35:21', 21, 258562784, NULL, 1),
