INSERT INTO `products` (`product_id`, `name`, `description`, `usage_instructions`, `ingredients_text`, `brand_id`, `category_id`, `base_price`, `is_featured`, `average_rating`, `sale_price`, `sale_start_date`, `sale_end_date`, `status`, `created_at`, `updated_at`) VALUES
(109129, 'A\'Pieu Juicy Pang Water Blusher 液體腮紅', 'A\'Pieu Fresh Tint Water Blusher 液體腮紅 水潤服貼，輕盈暈染，打造自然紅潤妝感。細緻液態質地，持久顯色，呈現柔和透亮光澤，輕鬆打造清新動人頰彩。', '取適量塗於顴骨。用指尖或海綿混合。\n\n*使用前請搖勻。', '水、環五聚二甲基矽氧烷、變性酒精、丁二醇、鯨蠟醇乙基己酸酯、甲基聚三甲基矽氧烷、滑石粉、甘油、戊二醇、peg-10 聚二甲基矽氧烷、三異辛酸甘油酯、合成氟金雲母、甲基丙烯酸甲酯交聯聚合物、聚甲基矽倍半氧烷、三甲基矽烷氧基矽酸酯、雲母 (CI 77019)、硫酸鎂、苯氧乙醇、鯨蠟基 PEG/PPG-10/1 聚二甲基矽氧烷、二硬脂基二甲基胺鋰皁石、二甲矽油、紅色 30 (ci 73360)、聚二甲基矽氧烷交聯聚合物、香料（香精）、三乙氧基辛基矽烷、乙基己基甘油、氧化鐵 (ci 77492)、乙二胺四乙酸二鈉、氧化鐵 (ci 77499)、歐洲甜櫻桃果實提取物、突厥薔薇花水、橙皮油、荷荷巴籽油、油茶籽油、黑種草籽油、石榴籽油、玫瑰果油、葡萄果提取物、杏果提取物、1, 2-己二醇、草莓果實提取物、桃果提取物、辛甘醇、辛二醇', 2, 4, 220.00, 0, 0, NULL, NULL, NULL, 'active', '2025-05-08 03:12:38', '2025-05-08 03:12:38'),
(109130, 'A\'Pieu Lush Tint Water Blusher 液體腮紅', 'A\'Pieu Lush Tint Water Blusher 液體腮紅  \n輕盈服貼，水潤暈染，打造自然紅潤頰彩。細緻液態質地，持久顯色不厚重，呈現柔和透亮光澤，展現清新動人妝感。', '取適量塗於顴骨。用指尖或海綿混合。*使用前請搖勻。', '水、環五聚二甲基矽氧烷、變性酒精、丁二醇、鯨蠟醇乙基己酸酯、甲基聚三甲基矽氧烷、滑石粉、甘油、戊二醇、peg-10 聚二甲基矽氧烷、三異辛酸甘油酯、合成氟金雲母、甲基丙烯酸甲酯交聯聚合物、聚甲基矽倍半氧烷、三甲基矽烷氧基矽酸酯、雲母 (CI 77019)、硫酸鎂、苯氧乙醇、鯨蠟基 PEG/PPG-10/1 聚二甲基矽氧烷、二硬脂基二甲基胺鋰皁石、二甲矽油、氧化鐵 (ci 77491)、聚二甲基矽氧烷交聯聚合物、香料、二氧化鈦 (ci 77891)、三乙氧基辛基矽烷、紅色 30 (ci 73360)、乙基己基甘油、乙二胺四乙酸二鈉、氧化鐵 (ci 77492)、歐洲甜櫻桃果實提取物、突厥薔薇花水、無花果果實提取物、橙皮油、荷荷巴籽油、油茶籽油、黑種草籽油、石榴籽油、玫瑰果油、葡萄果提取物、杏果提取物、1, 2-己二醇、藍莓果提取物、草莓果實提取物、桃果提取物、樹莓果實提取物、蘋果提取物、辛甘醇、辛二醇、甜橙果提取物、柿果提取物、胡桃殼提取物、桑葚提取物、石榴果實提取物、梨提取物、番茄果實提取物。', 2, 4, 220.00, 0, 0, NULL, NULL, NULL, 'active', '2025-05-08 03:12:38', '2025-05-08 03:12:38'),
(109134, 'A\'Pieu Dewy Glow Water Blusher 液體腮紅', 'A\'Pieu Dewy Glow Water Blusher 液體腮紅  \n水潤輕盈，服貼肌膚，打造自然透亮紅潤感。細緻液態質地，輕鬆暈染，持久顯色，呈現水感光澤，打造生動柔和妝效。', '取適量塗於顴骨。用指尖或海綿混合。\n\n使用前請搖勻。', '水、環五聚二甲基硅氧烷、變性酒精、丁二醇、鯨蠟醇乙基己酸酯、甲基聚三甲基硅氧烷、滑石粉、甘油、戊二醇、peg-10 聚二甲基硅氧烷、三異辛酸甘油酯、雲母 (CI 77019)、合成氟金雲母、甲基丙烯酸甲酯交聯聚合物、聚甲基硅倍半氧烷、三甲基硅烷氧基硅酸酯、二氧化鈦 (CI 77891)、硫酸鎂、苯氧乙醇、鯨蠟基 PEG/PPG-10/1 聚二甲基硅氧烷、二硬脂基二甲基胺鋰皁石、二甲硅油、紅色 30 (ci 73360)、聚二甲基硅氧烷交聯聚合物、香料、氧化鐵 (CI 77492)、三乙氧基辛基硅烷、氧化鐵 (ci 77491)、乙基己基甘油、乙二胺四乙酸二鈉、羣青 (CI 77007)、氧化鐵 (ci 77499)、歐洲甜櫻桃果實提取物、突厥薔薇花水、無花果提取物、橙皮油、荷荷巴籽油、油茶籽油、黑種草籽油、石榴籽油、玫瑰果油、葡萄果提取物、杏果提取物、1, 2-己二醇、藍莓果實提取物、草莓果實提取物、桃果提取物、樹莓果實提取物、葡萄柚果實提取物、辛甘醇、辛二醇。', 2, 4, 201.00, 0, 0, 165.00, '2025-05-05 06:39:08', '2025-08-16 14:09:08', 'active', '2025-05-08 03:12:38', '2025-05-08 03:12:38'),
