INSERT INTO `product_reviews` (`review_id`, `product_id`, `stock_id`, `user_id`, `rating`, `comment_text`, `is_anonymous`, `status`, `created_at`) VALUES
(1, 133714, 1, 60, 5, '我甚至想囤貨，深怕買不到！', 0, 'approved', '2025-05-08 10:11:51'),
(2, 133714, 1, 99, 3, '大致上不錯，就是妝效沒想像中那麼服貼。 上妝後的膚感還不錯，但妝不夠持久。 用了一週，沒有明顯好轉也沒變差。 包裝蠻好看的，效果就中等。 妝感自然，但上臉後膚質感提升。 如果打折可以試試，原價就有點猶豫。 偏乾膚質用可能會有點卡。', 0, 'approved', '2025-03-16 10:11:51'),
(3, 133714, 1, 13, 4, '上妝後的膚感還不錯，但妝不夠持久。 妝感不會太厚重，但也沒有特別出色。 外型加分，需要補妝但不影響整體。 塗上去有質感，但維持度有限。 如果不要求太多，這款可以接受。 妝感不會太厚重，但也沒有特別出色。', 0, 'approved', '2025-04-15 10:11:51'),
(4, 133714, 1, 70, 5, '買回家試了一次就馬上下單第二瓶！太喜歡Unleashia Ash Brown 眉筆了～', 0, 'approved', '2025-01-19 10:11:51'),
(5, 133714, 1, 9, 5, '質地清爽不悶，夏天用也超舒服～ 一整天都不脫妝，妝感乾淨自然太給力了！ 我甚至想囤貨，深怕買不到！ Unleashia這次的Unleashia Ash Brown 眉筆真的超越預期，完全是學生黨的救星！ Unleashia Ash Brown 眉筆真的讓我找回對化妝的熱情～', 0, 'approved', '2025-01-09 10:11:51'),
(6, 133714, 1, 36, 4, '我甚至想囤貨，深怕買不到！', 0, 'approved', '2024-12-24 10:11:51'),
(7, 133714, 1, 50, 5, '買回家試了一次就馬上下單第二瓶！太喜歡Unleashia Ash Brown 眉筆了～', 0, 'approved', '2024-12-18 10:11:51'),
(8, 133714, 1, 41, 3, '塗上去有質感，但維持度有限。 適合日常妝，但對我來說妝效偏啞光稍微不足。 適合新手練習用，老手可能會覺得普通。', 0, 'approved', '2025-02-09 10:11:51'),
(9, 133714, 1, 55, 2, '妝感不會太厚重，但也沒有特別出色。', 0, 'approved', '2025-05-08 10:11:51'),
(10, 133714, 1, 52, 5, '用了Unleashia Ash Brown 眉筆之後每天都期待化妝，搭配妝前乳效果比較好。 Unleashia Ash Brown 眉筆已經變成我化妝包裡的固定班底！ 妝效真的超自然，感覺像天生好膚質一樣！', 0, 'approved', '2025-02-22 10:11:51'),
(11, 133714, 1, 93, 5, 'Unleashia Ash Brown 眉筆真的讓我找回對化妝的熱情～ Unleashia太懂我們了，Unleashia Ash Brown 眉筆完全打中我的需求～ 沒想到開架也能有這麼好的品質，Unleashia好猛！ 每次出門都會用Unleashia Ash Brown 眉筆，因為真的妝效自然到爆！', 0, 'approved', '2024-12-16 10:11:51'),
(12, 133714, 1, 8, 2, '剛開始還好，但後面覺得妝前保濕很重要越來越不舒服。', 0, 'approved', '2025-03-07 10:11:51'),
(13, 133714, 1, 63, 5, '用了Unleashia Ash Brown 眉筆之後真的離不開了，妝容易崩壞到我感動！ 質地細緻不卡紋，平常趕時間用它很方便。 超越專櫃品質，用過一次就愛不釋手。', 0, 'approved', '2025-02-21 10:11:51'),
(14, 133714, 1, 88, 5, '一整天都不脫妝，上臉不會厚重太給力了！ 真的有種明星妝感的感覺，出油後妝感變得更服貼到炸裂！ 膚色暗沉都能瞬間提亮，保濕力夠太強！', 0, 'approved', '2024-11-09 10:11:51'),
(15, 133714, 1, 53, 5, '完全不輸專櫃，Unleashia的Unleashia Ash Brown 眉筆讓我大開眼界！ 這款Unleashia Ash Brown 眉筆真的太好用了，出油後妝感更自然，回購無數次！ 超越專櫃品質，用過一次就愛不釋手。 Unleashia Ash Brown 眉筆是近期用過最驚喜的美妝品，會有點氧化偏黃完全對得起價格！', 0, 'approved', '2025-03-09 10:11:51'),
(16, 133714, 1, 98, 4, '一用就驚艷，Unleashia Ash Brown 眉筆的妝感真的太美了！ 真的有種明星妝感的感覺，膚色顯得更均勻到炸裂！ 看得出來Unleashia真的用心設計這款Unleashia Ash Brown 眉筆。', 0, 'approved', '2024-11-26 10:11:51'),
(17, 133714, 1, 30, 2, '期待太高了，有點小失望，Unleashia這款Unleashia Ash Brown 眉筆不太合我。 這款Unleashia Ash Brown 眉筆妝感太厚重了，不太自然。 期待太高了，有點小失望，Unleashia這款Unleashia Ash Brown 眉筆不太合我。 剛開始還好，但後面覺得妝前保濕很重要越來越不舒服。', 0, 'approved', '2025-02-13 10:11:51'),
(18, 133714, 1, 57, 5, 'Unleashia Ash Brown 眉筆完全是素顏偽裝神器！ 終於找到命定粉底！感謝Unleashia～ Unleashia Ash Brown 眉筆是近期用過最驚喜的美妝品，粉底融合度高完全對得起價格！ 如果只能帶一樣底妝出門，那一定是Unleashia Ash Brown 眉筆！ 香味也很好聞，用起來超療癒～', 0, 'approved', '2025-04-12 10:11:51'),
(19, 133714, 1, 95, 4, '對新手友善，但老手會覺得功能不夠。 保濕效果有點弱，其它部分還可以。 如果沒其他選擇，這款還算堪用。', 0, 'approved', '2025-01-06 10:11:51'),
(20, 133714, 1, 4, 4, '之前看到網紅推薦，果然沒失望！ 真的有種明星妝感的感覺，妝容不夠乾爽到炸裂！ 沒想到開架也能有這麼好的品質，Unleashia好猛！ 真的不用修圖，Unleashia Ash Brown 眉筆直接讓我上鏡！ Unleashia這次的Unleashia Ash Brown 眉筆真的超越預期，需要補妝，不過補完妝效還是好看的。', 0, 'approved', '2025-01-02 10:11:51'),
(21, 133714, 1, 35, 3, '試用過幾次，目前覺得Unleashia Ash Brown 眉筆算是平價裡的中上程度。 Unleashia Ash Brown 眉筆妝效還算乾淨，但不特別出色。 整體還行，但Unleashia價格稍微偏高。', 0, 'approved', '2025-05-05 10:11:51'),
(22, 133714, 1, 61, 2, '有修飾效果，但不是太明顯。 平常用沒問題，但特別場合不太敢靠它。', 0, 'approved', '2025-04-23 10:11:51'),
(23, 133714, 1, 99, 4, '完全不卡粉不浮粉，乾肌也能安心使用！ 太穩了！Unleashia根本是底妝天花板！ Unleashia這次的Unleashia Ash Brown 眉筆真的超越預期，有一兩次會起屑，不過大部分都OK。 這款Unleashia Ash Brown 眉筆真的太好用了，整體不脫妝，回購無數次！', 0, 'approved', '2025-01-24 10:11:51'),
(24, 133714, 1, 14, 2, '覺得Unleashia Ash Brown 眉筆有點難推開，剛開始不太習慣，但越用越順手。 覺得Unleashia Ash Brown 眉筆有點難推開，比起其他同價位算表現不錯了。 這款Unleashia Ash Brown 眉筆妝感太厚重了，不太自然。 這款Unleashia Ash Brown 眉筆妝感太厚重了，不太自然。', 0, 'approved', '2025-02-04 10:11:51'),
(25, 133714, 1, 70, 2, '這款Unleashia Ash Brown 眉筆妝感太厚重了，不太自然。 期待太高了，有點小失望，Unleashia這款Unleashia Ash Brown 眉筆不太合我。 這款Unleashia Ash Brown 眉筆妝感太厚重了，不太自然。 可能不適合我的膚質，Unleashia Ash Brown 眉筆用了有點乾。 覺得Unleashia Ash Brown 眉筆有點難推開，大多時候表現穩定，有幾次出油快。 覺得Unleashia Ash Brown 眉筆有點難推開，妝感偏輕透，想遮瑕的可能要搭配其他產品。', 0, 'approved', '2025-04-20 10:11:51'),
(26, 133714, 1, 7, 5, '第一次用就愛上了，Unleashia Ash Brown 眉筆太厲害了！ 真的不用修圖，Unleashia Ash Brown 眉筆直接讓我上鏡！ 不論濕敷或厚敷都表現優秀，愛死了！', 0, 'approved', '2024-11-21 10:11:51'),
(27, 133714, 1, 25, 5, '終於找到命定粉底！感謝Unleashia～ 我已經回購三次，完全不想換品牌了！ 出門前必用Unleashia Ash Brown 眉筆，讓我一整天都自信滿滿。', 0, 'approved', '2025-02-05 10:11:51'),
(28, 133714, 1, 6, 5, '之前看到網紅推薦，果然沒失望！', 0, 'approved', '2025-04-21 10:11:51'),
(29, 133714, 1, 52, 5, '每次出門都會用Unleashia Ash Brown 眉筆，因為真的妝效自然到爆！ 妝效真的超自然，感覺像天生好膚質一樣！ Unleashia Ash Brown 眉筆真的讓我找回對化妝的熱情～ 每次用Unleashia的Unleashia Ash Brown 眉筆都覺得自己像女主角一樣美！ 第一次用就愛上了，Unleashia Ash Brown 眉筆太厲害了！ Unleashia Ash Brown 眉筆已經變成我化妝包裡的固定班底！ 平價卻有高級感，CP值超高！', 0, 'approved', '2025-04-26 10:11:51'),
(30, 133714, 1, 42, 4, 'Unleashia Ash Brown 眉筆完全是素顏偽裝神器！ Unleashia太懂我們了，Unleashia Ash Brown 眉筆完全打中我的需求～ Unleashia太懂我們了，Unleashia Ash Brown 眉筆完全打中我的需求～ 質地清爽不悶，夏天用也超舒服～', 0, 'approved', '2024-12-22 10:11:51'),
(31, 133714, 1, 55, 2, '覺得Unleashia Ash Brown 眉筆有點難推開，整體感覺不錯，但沒有到非它不可。 剛開始還好，但後面覺得會微微浮在毛孔上越來越不舒服。 可能不適合我的膚質，Unleashia Ash Brown 眉筆用了有點乾。', 0, 'approved', '2025-04-07 10:11:51'),
(32, 133714, 1, 46, 4, '買回家試了一次就馬上下單第二瓶！太喜歡Unleashia Ash Brown 眉筆了～ 如果只能帶一樣底妝出門，那一定是Unleashia Ash Brown 眉筆！ 簡直是學生黨的救星，Unleashia Ash Brown 眉筆太值得買了！ 這款Unleashia Ash Brown 眉筆真的太好用了，有點浮粉，回購無數次！ 質地柔滑服貼，沒預期中那麼驚艷，但也沒踩雷。！', 0, 'approved', '2025-03-10 10:11:51'),
(33, 133714, 1, 67, 4, '平價卻有高級感，CP值超高！ 超適合上班族！快速完妝又不卡粉！ 早上上妝，晚上還是美到不行！ 感謝Unleashia推出的Unleashia Ash Brown 眉筆，我每天都在用，塗完不會黏膩，這點不錯。 妝效真的超自然，感覺像天生好膚質一樣！ 終於找到命定粉底！感謝Unleashia～ 質地清爽不悶，夏天用也超舒服～', 0, 'approved', '2024-12-10 10:11:51'),
(34, 133714, 1, 93, 3, 'Unleashia Ash Brown 眉筆妝效還算乾淨，但不特別出色。 顏色選擇普通，適合基本妝容。 用了不會過敏就加分，但效果真的就普通。', 0, 'approved', '2024-11-22 10:11:51'),
(35, 133714, 1, 67, 5, '一整天都不脫妝，妝感不厚重太給力了！ Unleashia這次的Unleashia Ash Brown 眉筆真的超越預期，需要補妝，不過補完妝效還是好看的。 香味也很好聞，用起來超療癒～', 0, 'approved', '2025-03-10 10:11:51'),
(36, 133714, 1, 56, 4, '沒想到開架也能有這麼好的品質，Unleashia好猛！ 買回家試了一次就馬上下單第二瓶！太喜歡Unleashia Ash Brown 眉筆了～ 我已經回購三次，完全不想換品牌了！ 用了Unleashia Ash Brown 眉筆之後每天都期待化妝，完全是學生黨的救星！ 包裝美質感佳，內容物更是讓人滿意到不行！', 0, 'approved', '2025-03-23 10:11:51'),
